                      "quoteExcerpt": "{\"data\": [{\"hovertemplate\": \"资金类型: %{x}\u003cbr>净额: %{y:+.1f}万元\u003cextra>\u003c/extra>\", \"marker\": {\"color\": [\"#188038\", \"#188038\", \"#188038\", \"#D93025\"]}, \"text\": [\"-899.5万\", \"-1376.5万\", \"-1218.3万\", \"+2594.8万\"], \"textfont\": {\"size\": 13}, \"textposition\": \"outside\", \"x\": [\"特大单\", \"大单(DDE)\", \"中单\", \"小单(散户)\"], \"y\": [-899.49, -1376.46, -1218.35, 2594.81], \"type\": \"bar\"}], \"layout\": {\"template\": {\"data\": {\"barpolar\": [{\"marker\": {\"line\": {\"color\": \"white\", \"width\": 0.5}, \"pattern\": {\"fillmode\": \"overlay\", \"size\": 10, \"solidity\": 0.2}}, \"type\": \"barpolar\"}], \"bar\": [{\"error_x\": {\"color\": \"#2a3f5f\"}, \"error_y\": {\"color\": \"#2a3f5f\"}, \"marker\": {\"line\": {\"color\": \"white\", \"width\": 0.5}, \"pattern\": {\"fillmode\": \"overlay\", \"size\": 10, \"solidity\": 0.2}}, \"type\": \"bar\"}], \"carpet\": [{\"aaxis\": {\"endlinecolor\": \"#2a3f5f\", \"gridcolor\": \"#C8D4E3\", \"linecolor\": \"#C8D4E3\", \"minorgridcolor\": \"#C8D4E3\", \"startlinecolor\": \"#2a3f5f\"}, \"baxis\": {\"endlinecolor\": \"#2a3f5f\", \"gridcolor\": \"#C8D4E3\", \"linecolor\": \"#C8D4E3\", \"minorgridcolor\": \"#C8D4E3\", \"startlinecolor\": \"#2a3f5f\"}, \"type\": \"carpet\"}], \"choropleth\": [{\"colorbar\": {\"outlinewidth\": 0, \"ticks\": \"\"}, \"type\": \"choropleth\"}], \"contourcarpet\": [{\"colorbar\": {\"outlin\n\n[……中间省略 6601 字符……]\n\n, \"r\": 24, \"t\": 80, \"b\": 56}, \"yaxis\": {\"title\": {\"text\": \"净额（万元）\"}, \"zeroline\": true, \"zerolinewidth\": 1.5, \"zerolinecolor\": \"#6B7280\"}, \"xaxis\": {\"title\": {\"text\": \"资金类型\"}}, \"height\": 420, \"showlegend\": false}, \"config\": {\"modeBarButtonsToRemove\": [\"toImage\", \"lasso2d\", \"sendDataToCloud\", \"select2d\", \"resetScale2d\", \"zoom2d\", \"pan2d\"], \"displaylogo\": false, \"plotlyServerURL\": \"https://plot.ly\"}}",
                      "quoteTruncated": true,
