                      "message_index": 0,
                      "quoteExcerpt": "ST亿晶26/5/19大幅上涨，主要原因是什么？",
                      "quoteTruncated": false,
                      "quoteCharacters": 24,
                      "provenance": {
                        "file": "data/runs/comparison/daily-2026-10-09/results/attribution.jsonl",
                        "line": 32,
                        "pointer": "/evaluation/criterion_assessments/0/evidence/2/quote"
                      }
